/// Hydrates from a yrs v1 update. The first load after an unseeded open retains prior
/// comment writes and marks loaded fields differing from seed placeholders as authored.
pub fn load(&self, update: &[u8]) -> Result<(), JsValue> {
    let session_id = self.engine.doc().session_id();
    let written = self.awaiting_comment_baseline.get().then(|| {
        self.engine
            .doc()
            .source_metadata()
            .map(|source| source.read().comment_writes.snapshot())
            .unwrap_or_default()
    });
    self.engine.doc().load_state_v1(update).map_err(js_err)?;
    if self.engine.doc().session_id() != session_id {
        self.engine.set_relayout_trigger(RelayoutTrigger::Open);
    }
    if let Some(written) = written {
        self.engine.doc().rebase_comment_writes(written);
        self.awaiting_comment_baseline.set(false);
    }
    self.engine.doc().rotate_version(js_entropy());
    Ok(())

/// Starts local-origin undo tracking across every story. Call this after
/// import or seeding but before the first edit, so the initial document is
/// not an undo step; later calls keep the history.
pub fn track_undo(&self) {
    self.undo.track(self.engine.doc());
}

/// Returns None for pending data, unstable JSON values, root sequence content, or deleted content
/// a fork would collect; a fork that `keeps_deleted`, as one of a replica with an undo history
/// does, collects none.
pub(crate) fn fork_state_len_v1<T: ReadTxn>(txn: &T, keeps_deleted: bool) -> Option<usize> {
    let store = txn.store();
    if store.pending_update().is_some() || store.pending_ds().is_some() {
        return None;
    }
    let mut encoder = CountingEncoderV1::default();
    txn.encode_state_as_update(&StateVector::default(), &mut encoder);
    (!encoder.unstable_json
        && !encoder.root_sequence
        && (keeps_deleted || encoder.tombstone_len == encoder.deleted_len))
        .then_some(encoder.len)
